import functools
import time

def timer(func):

	@functools.wraps(func)
	def wrapper(*args, **kwargs):
		stime = time.perf_counter()
		res = func(*args, **kwargs)
		elapsed = time.perf_counter() - stime
		print(f'{func.__name__} in {elapsed:.4f} secs')
		return res
	return wrapper

class solver:

	def __init__(self):
		t = int(input())
		a = list(map(int, input().strip().split()))

		def build(n, m, r, c):
			if not (0 <= r and r < n and (0 <= c) and (c < m)):
				return []
			ret = [0] * t
			for i in range(n):
				for j in range(m):
					ret[abs(r - i) + abs(c - j)] += 1
			return ret
		a.sort()
		h = [0] * t
		amax = 0
		for ai in a:
			h[ai] += 1
			amax = max(amax, ai)
		r = 0
		while r + 1 < t and h[r + 1] == (r + 1) * 4:
			r += 1
		n = 1
		while n * n <= t:
			for transposed in [False, True]:
				if t % n == 0:
					m = t // n
					c = n - 1 - r + (m - 1 - amax)
					f = build(n, m, r, c) if not transposed else build(n, m, c, r)
					if h == f:
						print(f'{n} {m}')
						if not transposed:
							print(f'{r + 1} {c + 1}')
						else:
							print(f'{c + 1} {r + 1}')
						exit(0)
			n += 1
		print('-1')
solver()
